package com.gameaggregator.apikeyservice.api;import jakarta.validation.constraints.*;import java.time.Instant;import java.util.*;import java.util.UUID;public final class ApiKeyDtos{private ApiKeyDtos(){}public record Create(@NotNull UUID tenantId,@NotNull UUID clientId,@NotNull UUID environmentId,@NotEmpty Set<@Pattern(regexp="[a-z0-9-]+:[a-z0-9-]+") String> scopes,Set<@NotBlank String> ipAllowlist,@Positive long quota,Instant expiresAt){}public record Issued(UUID id,String apiKey,String prefix,String lastFour,Instant expiresAt){}public record View(UUID id,UUID tenantId,UUID clientId,UUID environmentId,String prefix,String lastFour,Set<String> scopes,Set<String> ipAllowlist,long quota,String status,Instant expiresAt,Instant revokedAt){}public record Verification(boolean valid,UUID tenantId,UUID clientId,UUID environmentId,Set<String> scopes,long quota,String reason){}}